(function () {
  const { title, h, list, fx, card, flow, cols, split, tbl, svg, at } = VK;
  // latent interpolation: faces whose mouth curve goes from frown to smile
  const face = (c, lab) => `<svg viewBox="0 0 60 72" class="fc"><circle cx="30" cy="28" r="24"/><circle cx="21" cy="22" r="2.6" class="e"/><circle cx="39" cy="22" r="2.6" class="e"/><path d="M18 ${(37 - c / 3).toFixed(1)} Q30 ${(37 + c).toFixed(1)} 42 ${(37 - c / 3).toFixed(1)}"/><text x="30" y="68">${lab}</text></svg>`;
  const faces = (k) => at(k, `<div class="fcs">${[-9, -4.5, 0, 4.5, 9].map((c, i) => `<div class="vk-i" data-s="${k + (i === 0 || i === 4 ? 0 : 1)}">${face(c, i === 0 ? "z<tspan baseline-shift='sub' font-size='7'>A</tspan>" : i === 4 ? "z<tspan baseline-shift='sub' font-size='7'>B</tspan>" : "")}</div>`).join("")}</div>`);
  // diffusion strip: noise → shape. Seeded random (seed 67) so the picture is stable.
  let seed = 67; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const dots = Array.from({ length: 140 }, () => [rnd() * 60, rnd() * 60]);
  const step = (t, i) => `<svg viewBox="0 0 60 60" class="df"><rect width="60" height="60" rx="6"/><g opacity="${t}"><circle cx="30" cy="30" r="17" class="sh"/><circle cx="24" cy="26" r="2.5" class="ey"/><circle cx="36" cy="26" r="2.5" class="ey"/><path d="M22 35 Q30 42 38 35" class="mo"/></g>${dots.slice(0, Math.round((1 - t) * 140)).map(([x, y]) => `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="1.4" class="nz"/>`).join("")}</svg>`;
  const diffusion = (k) => at(k, `<div class="dfs">${[0, 0.25, 0.5, 0.75, 1].map((t, i) => `<div class="vk-i" data-s="${k + Math.min(i, 2)}">${step(t, i)}<span>${i === 0 ? "pure noise" : i === 4 ? "image" : "denoise"}</span></div>`).join("<b>→</b>")}</div>`);

  const { stg, act, fix, tag, say, person, J } = VK;
  // discriminative boundary vs generative clouds (seeded 67 via rnd above)
  const CA = Array.from({ length: 9 }, () => [60 + rnd() * 70, 40 + rnd() * 60]), DG = Array.from({ length: 9 }, () => [170 + rnd() * 70, 50 + rnd() * 60]);
  const pts9 = (dx) => CA.map(([x, y]) => `<circle class="ca9" cx="${x + dx}" cy="${y}" r="5"/>`).join("") + DG.map(([x, y]) => `<rect class="dg9" x="${x + dx - 4.5}" y="${y - 4.5}" width="9" height="9"/>`).join("");
  const discGen = `<svg class="vk-g dgv9" viewBox="0 0 600 150"><g>${pts9(0)}<line class="bd9" x1="150" y1="20" x2="160" y2="125"/><text class="lt9" x="150" y="145" text-anchor="middle">discriminative: just the line, P(y | x)</text></g>
    <g class="vk-i" data-s="1">${pts9(300)}<ellipse class="cl9 a" cx="${395}" cy="70" rx="48" ry="40"/><ellipse class="cl9 b" cx="${505}" cy="80" rx="48" ry="40"/><circle class="nw9" cx="410" cy="62" r="7"/><text class="lt9 b" x="420" y="50">new sample</text><text class="lt9" x="450" y="145" text-anchor="middle">generative: the whole shape, P(x)</text></g></svg>`;
  // pins (AE) vs clouds (VAE), then a random probe
  const PINS = [[70, 45], [150, 80], [110, 100], [200, 50], [230, 105]];
  const pinsClouds = `<svg class="vk-g pcv9" viewBox="0 0 600 140"><g class="vk-i" data-s="1">${PINS.map(([x, y]) => `<circle class="pin9" cx="${x}" cy="${y}" r="5"/>`).join("")}<text class="lt9" x="150" y="135" text-anchor="middle">AE: exact pins, empty gaps</text></g>
    <g class="vk-i" data-s="2">${PINS.map(([x, y]) => `<circle class="cld9" cx="${x + 300}" cy="${y}" r="38"/><circle class="pin9" cx="${x + 300}" cy="${y}" r="4"/>`).join("")}<text class="lt9" x="450" y="135" text-anchor="middle">VAE: fuzzy clouds fill the map</text></g>
    <g class="vk-i" data-s="3"><circle class="prb9" cx="180" cy="20" r="6"/><text class="lt9 bad" x="190" y="24">random spot → garbage</text><circle class="prb9" cx="480" cy="20" r="6"/><text class="lt9 ok" x="490" y="24">random spot → sensible</text></g></svg>`;
  // anomaly detection: reconstruction error bars and a threshold
  const ERR = [0.02, 0.03, 0.015, 0.025, 0.02, 0.018, 0.35];
  const anom = at(2, `<div class="an9"><b class="th9"><span>threshold 0.10</span></b>${ERR.map((e, i) => `<div><i class="${i === 6 ? "x" : ""}" data-st='${J({ 2: "height:" + (e / 0.4 * 100).toFixed(1) + "%" })}' style="height:0%;transition-delay:${i * 0.15}s"></i><span>${i === 6 ? "new: 0.35" : e}</span></div>`).join("")}</div>`);
  // reparameterisation on a number line
  const RX = v => 300 + v * 110, bell = (mu, sg, hh) => { let d = ""; for (let i = 0; i <= 80; i++) { const v = -2.6 + i * 0.065, y = 78 - hh * Math.exp(-((v - mu) ** 2) / (2 * sg * sg)); d += (i ? "L" : "M") + RX(v).toFixed(1) + " " + y.toFixed(1); } return d; };
  const repar = `<svg class="vk-g rp9" viewBox="0 0 600 112"><line class="ax9" x1="${RX(-2.6)}" y1="78" x2="${RX(2.6)}" y2="78"/>${[-2, -1, 0, 1, 2].map(v => `<line class="ax9" x1="${RX(v)}" y1="74" x2="${RX(v)}" y2="82"/><text class="lt9" x="${RX(v)}" y="96" text-anchor="middle">${v < 0 ? "−" + -v : v}</text>`).join("")}
    <path class="vk-i bl9" data-s="2" d="${bell(0, 1, 34)}"/><text class="vk-i lt9" data-s="2" x="${RX(-1.6)}" y="40">ε ~ N(0, 1)</text>
    <path class="vk-i bl9 b" data-s="4" d="${bell(1, 0.5, 60)}"/><text class="vk-i lt9 ok" data-s="4" x="${RX(1.5)}" y="22">z ~ N(μ = 1, σ = 0.5)</text>
    <g class="mover ep9" data-run='${J({ 4: [[RX(0.4), 78], [RX(0.4), 78], [RX(0.2), 78], [RX(1.2), 78]] })}' data-dur="3000" style="opacity:0"><circle r="7"/></g>
    <text class="vk-i lt9 b" data-s="4" x="300" y="110" text-anchor="middle">draw ε = 0.4 → scale by σ (0.2) → shift by μ → z = 1.2</text></svg>`;
  // forger and detective
  const forger = [act(person("forger G", 2), { 0: [12, 55, 0], 1: [12, 55, 1] }), act(person("detective D", 4), { 0: [88, 55, 0], 1: [88, 55, 1] }),
    `<div class="a" data-run='${J({ 1: [[22, 50], [74, 50]], 3: [[22, 50], [74, 50]], 4: [[22, 50], [74, 50]] })}' data-dur="1600" style="opacity:0"><div class="tg note9">${say({ 1: "crayon banknote", 3: "better banknote", 4: "near-perfect banknote" })}</div></div>`,
    act(tag(say({ 2: "D: fake! P(real) = 0.1", 3: "D: hmm, P(real) = 0.3", 4: "D: can't tell. P(real) = 0.5" }), "hi"), { 0: [50, 12, 0], 2: [50, 12, 1] }),
    act(tag("each one's progress forces the other to improve", "lbl"), { 0: [50, 92, 0], 3: [50, 92, 1] })];
  // mode collapse: variety vs one repeated output
  const SH = ["●", "▲", "■", "◆", "✚"];
  const collapse = [fix(tag("real data", "lbl"), 9, 40, 1), fix(tag("G output", "lbl"), 9, 82, 1)]
    .concat(SH.map((c, i) => fix(`<div class="sh9 s${i}">${c}</div>`, 26 + i * 14, 40, 1)))
    .concat(SH.map((c, i) => fix(`<div class="sh9" data-on="1:s${i} 2:s0">${say({ 1: c, 2: "●" })}</div>`, 26 + i * 14, 82, 1)))
    .concat([act(tag(say({ 1: "success: same variety, D ≈ 0.5", 2: "mode collapse: one shape, over and over" }), ""), { 0: [50, 8, 0], 1: [50, 8, 1] })]);

  VIDEO_LESSONS.l9 = {
    title: "L9: Generative AI", chapters: [
      { t: "What generative AI is", sec: [], scenes: [
        { v: title("Generative AI", "Week 9 lesson") + list([[1, "What GenAI is, its <b>history</b>, uses and the <b>latent space</b> idea"], [2, "<b>Autoencoders</b>: compress and rebuild"], [3, "<b>Variational autoencoders</b>: a distribution instead of a point"], [4, "<b>GANs</b>: a generator and a discriminator in a contest"], [5, "Transformers, diffusion, a comparison table, and <b>ethics</b>"]]),
          n: ["Welcome to week 9: generative AI. Until now most models we built looked at data and gave an answer, like a label or a value. This week the models create new content: text, images, music and video.",
            "We'll start with what generative AI is, where it came from, what it's used for, and the one idea everything rests on, the latent space.",
            "Then the first model family, autoencoders, which squeeze data down and rebuild it.",
            "Then variational autoencoders, which make that squeezed space smooth enough to sample new things from.",
            "Then generative adversarial networks, where two networks compete until the fakes look real.",
            "And we'll finish with transformer and diffusion models, a side by side comparison, and the ethical issues. Let's start."] },
        { v: h("Making new content from learned patterns") + card(0, "", "<b>Generative AI</b>: algorithms and models that produce <b>new content resembling their training data</b>. Purpose: automate creative work, boost productivity, open new applications in art, entertainment, design, content creation.") + tbl(["Technique", "Core idea", "Typical uses"], [[1, "<b>VAE</b>", "Encode to a latent space, decode back. <b>Sampling</b> the latent space gives diverse outputs.", "Image and music generation, anomaly detection"], [2, "<b>GAN</b>", "<b>Generator vs discriminator</b>. Fakes get judged, quality improves.", "Image and video generation, style transfer"], [3, "<b>Transformer autoregressive</b> (GPT)", "<b>Attention</b> generates sequences. Pre-train on big data, fine-tune.", "Language, chatbots, code generation"], [4, "<b>Diffusion</b>", "Start from <b>random noise</b>, <b>denoise</b> step by step.", "Text-to-image, audio synthesis"]], "sm"),
          n: ["Generative AI covers algorithms and models that produce new content resembling the data they were trained on. The main purpose is to automate creative work, boost productivity, and open new applications in art, entertainment, design and content creation. Most recent progress comes from deep learning.",
            "The module names four sample techniques. Variational autoencoders take a probabilistic approach: encode the input into a latent space and decode it back. Sampling from that space gives diverse outputs. They're used for image and music generation, and anomaly detection.",
            "Generative adversarial networks pit a generator against a discriminator. The generator makes fake data, the discriminator judges it, and quality improves over time. Uses include image generation, style transfer and video generation.",
            "Transformer-based autoregressive models, like GPT, use attention to generate text and other sequences. They're pre-trained on large datasets and fine-tuned for specific tasks, for chatbots, language processing and code.",
            "And diffusion models start from random noise and remove it step by step until a coherent structure appears. They power text-to-image tools and audio synthesis."] },
        { v: h("Applications and advantages") + split(list([[0, "<b>Content creation</b>: articles, stories, poetry, reports."], [0, "<b>Art and design</b>: visual art, logos, product designs from a prompt."], [1, "<b>Image and video synthesis</b>: entertainment, advertising, simulation."], [1, "<b>Music generation</b>: compose, or suggest melodies and harmonies."], [2, "<b>Synthetic data</b>: build training sets when real data is <b>scarce or sensitive</b>."]], "tight"), card(3, "tip", "<b>Enhanced creativity</b>: tools to explore new ideas and styles.") + card(3, "tip", "<b>Cost and time</b>: automate repetitive work, focus on higher-level decisions.") + card(3, "tip", "<b>Customisation</b>: personalised content from user preferences."), "even"),
          n: ["Where is it used? Content creation, like automated articles, stories, poetry and reports. Art and design, like visual art, logos and product designs, often guided by a user's prompt or theme.",
            "Image and video synthesis, for entertainment, advertising and simulation. And music generation, composing original music or helping musicians find new melodies and harmonies.",
            "One that's easy to forget in the exam: synthetic data generation. When real data is scarce or sensitive, like medical records, you can generate realistic training data instead.",
            "The three advantages the course lists: enhanced creativity, since creators get tools to explore new ideas and styles. Cost and time efficiency, since repetitive work is automated and people can focus on higher-level decisions. And customisation, producing personalised content based on user preferences."] }
      ] },
      { t: "Three kinds of model", sec: [0], scenes: [
        { v: h("Discriminative, generative, reinforcement") + at(0, discGen) + tbl(["Category", "Learns", "Examples"], [[0, "<b>Discriminative</b>", "A boundary or mapping from x to label y: <b>P(y | x)</b>. Needs labels (supervised).", "Classification, regression, object detection"], [1, "<b>Generative</b>", "The <b>data distribution P(x)</b> itself, so it can <b>create new samples</b>. Often unsupervised.", "AE, VAE, GAN, autoregressive, diffusion"], [2, "<b>Reinforcement</b>", "A <b>policy</b> (actions) from <b>rewards</b>.", "Q-learning, game playing"]], "sm") + split(list([[3, "Why generative? <b>Sampling</b>, <b>outlier detection</b>, <b>debiasing</b>."], [4, "<b>Latent variables z</b>: hidden factors behind x (pose, lighting, smile)."]], "tight"), card(5, "ana", "Discriminative = <b>art critic</b> (“this is a Monet”). Generative = <b>painter</b> of a new Monet."), "even"),
          n: ["Machine learning models fall into three categories. Discriminative models learn a boundary, or a mapping from input x to label y: the probability of y given x. They need labels, so they're supervised. Classification, regression and object detection are all discriminative.",
            "Generative models learn the data distribution itself, P of x. Once you know what the data looks like, you can create new samples from it. They're often unsupervised. Autoencoders, VAEs, GANs, autoregressive models and diffusion models are all generative.",
            "Reinforcement learning, from week 6, learns a policy, meaning which actions to take, from rewards. Q-learning and game-playing agents.",
            "Why bother with generative models? Generating new samples, obviously. But also outlier detection, since something that doesn't fit the learned distribution stands out. And debiasing datasets, by uncovering hidden features that are over or under represented.",
            "A key word: latent variables, written z. These are hidden factors that explain the data you observe. For face photos, z might capture pose, lighting, or how much the person is smiling. A generative model learns how z gives rise to x.",
            "The analogy: a discriminative model is an art critic who can say this is a Monet. A generative model is a painter who can paint a brand new Monet-style picture."] }
      ] },
      { t: "A short history", sec: [], scenes: [
        { v: h("Five stages of generative AI") + split(tbl(["When", "Milestone"], [[0, "<b>1950</b>", "Turing proposes the <b>Turing Test</b>"], [0, "<b>1956</b>", "<b>Dartmouth Conference</b>: birth of AI"], [0, "<b>1966</b>", "<b>ELIZA</b> (Weizenbaum): pattern-matching chat"], [1, "<b>1980s</b>", "Statistical and probabilistic AI"], [1, "<b>1990s</b>", "<b>HMMs</b>: speech, sequences"], [1, "1990s-2000s", "Neural nets return, slowly"]], "sm"), tbl(["When", "Milestone"], [[2, "<b>2012</b>", "<b>AlexNet</b> wins ImageNet"], [2, "<b>2013</b>", "<b>VAEs</b> (Kingma and Welling)"], [2, "<b>2014</b>", "<b>GANs</b> (Ian Goodfellow)"], [3, "<b>2019</b>", "<b>GPT-2</b>. Deepfake, bias concerns"], [4, "<b>2020</b>", "<b>GPT-3</b> and later LLMs"], [4, "<b>2021-22</b>", "<b>DALL-E</b>, <b>Stable Diffusion</b>"], [4, "Recent", "<b>Multimodal</b>: CLIP, GPT-4"]], "sm"), "even") + card(5, "", "Open: <b>interpretability</b>, <b>bias</b>, ethics. Next: personalisation, healthcare, education, AR/VR."),
          n: ["Generative AI's history is usually split into five stages. Stage 1, early foundations, 1950s to 1980s. In 1950 Alan Turing publishes Computing Machinery and Intelligence and proposes the Turing Test. In 1956 the Dartmouth Conference, organised by McCarthy, Minsky, Rochester and Shannon, is seen as the birth of AI. In 1966 Joseph Weizenbaum builds ELIZA, which holds a simulated conversation using keyword recognition and pattern matching, an early simple generative system.",
            "Stage 2, the rise of machine learning, 1980s to 2010s. Statistical and probabilistic approaches take hold. In the 1990s, Hidden Markov Models become popular for speech recognition and sequence generation. Neural networks return, but limited hardware and data slow progress.",
            "Stage 3, the deep learning revolution, the 2010s. AlexNet wins ImageNet in 2012. In 2013 Kingma and Welling introduce VAEs. In 2014 Ian Goodfellow introduces GANs. Those dates are worth memorising: VAE 2013, GAN 2014.",
            "Stage 4, expansion and application, 2015 to 2020. Generative models spread into text, music and video. GPT-2 in 2019 shows how coherent transformer text can be. Concerns about deepfakes, bias and misinformation start calls for responsible AI.",
            "Stage 5, maturity and mainstream adoption, 2021 onwards, with GPT-3 arriving in 2020. Large language models spread across industries. DALL-E in 2021 and Stable Diffusion in 2022 let anyone create images from text. Recent multimodal models like CLIP and GPT-4 work across text, image and audio.",
            "Open challenges remain: interpretability, bias in generated content, and frameworks for ethical use. Future directions include personalised content, healthcare, education, integration with augmented and virtual reality, and real-time customisation."] }
      ] },
      { t: "Latent space", sec: [], scenes: [
        { v: h("Latent space: a compressed map of the data") + card(0, "", "<b>Latent space</b>: a compressed, <b>lower-dimensional</b> representation of data that keeps its <b>essential features</b>. Easier to analyse, generate and manipulate.") + split(list([[1, "<b>Dimensionality reduction</b> and <b>features</b> (lighting, style)."], [2, "<b>Smooth interpolation</b>: neighbours are similar, paths <b>blend</b>."], [3, "<b>Generate</b>: <b>sample</b> a point → new data."], [3, "<b>Manipulate</b>: move a dimension → change age, mood."]], "tight"), faces(2) + fx(2, "walking from z<sub>A</sub> to z<sub>B</sub> blends a frown into a smile", "sm"), "even"),
          n: ["Autoencoders and GANs both rely on the idea of a latent space, so let's get comfortable with it. A latent space is a compressed, lower-dimensional representation of data that keeps its essential features. Real images, text and audio have huge numbers of dimensions. Mapping them into a latent space makes them much easier to analyse, generate and manipulate.",
            "Its key aspects. Dimensionality reduction: complex data becomes a simpler form. Feature representation: points stand for abstract features, so for images, different directions might capture lighting, orientation or style.",
            "Smooth interpolation: similar inputs land near each other, so moving between two points blends their characteristics. Here, z A is a frowning face and z B a smiling one. The points in between give faces part way between.",
            "Generative capability: in VAEs and GANs you can sample a point from the latent space and decode it into new data that shares the training set's properties but is unique. And exploration and manipulation: adjusting certain dimensions can control the output, like the apparent age of a face or the mood of a piece of music."] },
        { v: h("Latent representation: point or distribution?") + card(0, "", "<b>Latent representation</b>: the compressed vector that captures the essential features of <b>one input</b>.") + cols(card(1, "", "<b>Autoencoder</b>: <b>fixed</b>. Each input → <b>one static point</b>."), card(2, "tip", "<b>VAE</b>: <b>probabilistic</b>. Each input → a <b>distribution</b> (μ, σ).")) + at(1, pinsClouds) + card(3, "ana", "AE: each photo is a <b>pin</b> on a map, with gaps. VAE: each photo is a <b>fuzzy cloud</b>, clouds overlap, so any random spot decodes to something sensible."),
          n: ["A latent representation is the compressed vector, or in a VAE the distribution, that summarises one particular input.",
            "How it's produced is the big difference between our first two models. A traditional autoencoder gives a fixed latent representation: each input maps to one single, static point.",
            "A variational autoencoder gives a probabilistic latent representation: each input maps to a probability distribution, described by a mean and a variance, which captures the structure and variability of the data.",
            "The analogy from the revision notes. An autoencoder stores each photo as an exact pin on a map, with empty gaps between the pins. Pick a random spot and you may land in a gap that decodes to garbage. A VAE stores each photo as a fuzzy cloud. The clouds overlap and fill the map, so any random spot gives a sensible picture. Keep that in mind for the next two chapters."] }
      ] },
      { t: "Autoencoders", sec: [1], scenes: [
        { v: h("Autoencoder: compress, then rebuild") + split(svg("ae", 0), list([[0, "<b>Encoder</b>: x → small <b>latent code z</b>."], [1, "<b>Decoder</b>: z → <b>reconstruction x̂</b>."], [2, "Train so <b>x̂ ≈ x</b>. <b>No labels</b> (unsupervised)."], [3, "<b>Bottleneck</b>: z smaller than x → keep only what matters."], [4, "Smaller z = <b>tighter bottleneck</b> = worse reconstruction."]], "tight")) + card(5, "ana", "Summarise a movie in <b>one sentence</b> (encoder). Someone retells the whole movie from your sentence (decoder)."),
          n: ["An autoencoder is a neural network that learns a hidden encoding of its input, then reconstructs the input as closely as it can. It has two parts. The encoder compresses the input x into a low-dimensional latent code, z.",
            "The decoder takes z and rebuilds the input, giving the reconstruction, x hat.",
            "Training makes x hat as close to x as possible. Notice there are no labels. The original input acts as its own supervision signal, so this is unsupervised learning. Quiz point: an autoencoder is trained to reconstruct its input.",
            "The middle is called the bottleneck. z is smaller than x, so the network can't just copy everything through. It has to compress, and keep only the most important features.",
            "Make the latent space smaller and the bottleneck gets tighter. You get more compression, but usually a worse reconstruction, because more detail has to be thrown away.",
            "The analogy: summarising a whole movie in one sentence is the encoder. Someone retelling the movie from your sentence is the decoder. A good sentence keeps what matters."] },
        { v: h("Inside the encoder and decoder") + split(card(0, "", "<b>Encoder</b><br>Input layer → hidden layers that <b>shrink</b> dimensions (linear transform + <b>ReLU</b> or sigmoid) → latent output. Keeps essentials, <b>discards noise</b>.") + card(1, "", "<b>Decoder</b><br>Usually <b>mirrors</b> the encoder in reverse, expanding back to the original size. ReLU in hidden layers, <b>sigmoid or tanh</b> at the output (e.g. pixel values)."), fx(2, "MSE = (1/n) Σ<sub>i</sub> (x<sub>i</sub> − x̂<sub>i</sub>)<sup>2</sup>", "c") + fx(3, "x = [1, 0, 0.5, 1], &nbsp; x̂ = [0.9, 0.1, 0.5, 0.7]<br>errors² = 0.01, 0.01, 0, 0.09 → sum 0.11<br>MSE = 0.11 / 4 = <b>0.0275</b>", "sm") + list([[4, "<b>MSE</b> for continuous data, <b>binary cross-entropy</b> for binary data."], [5, "Same input and output <b>shape</b>. Often <b>symmetric</b>, but that's not a strict rule."]], "tight"), "even"),
          n: ["The encoder usually has an input layer, then hidden layers that progressively reduce the dimensions using linear transformations and non-linear activations like ReLU or sigmoid, then an output layer that gives the latent vector. The compression keeps the essential features and discards noise and less important detail.",
            "The decoder takes the latent vector and expands it back to the original size. It typically mirrors the encoder in reverse. ReLU is common in the hidden layers, with sigmoid or tanh at the output depending on the data, for example pixel values between 0 and 1.",
            "Both halves are trained together by minimising the reconstruction loss, which measures how far the output is from the input. Mean squared error is the usual choice: the average, over all n values, of the squared difference between x and x hat.",
            "A tiny example. x is 1, 0, 0.5, 1. The reconstruction is 0.9, 0.1, 0.5, 0.7. The squared errors are 0.01, 0.01, 0, and 0.09, which add to 0.11. Divide by 4 values and the MSE is 0.0275.",
            "Use mean squared error for continuous data, and binary cross-entropy for binary data.",
            "Two characteristics to remember. Input and output always have the same shape, because the goal is reconstruction. And many autoencoders are symmetric, with the decoder mirroring the encoder, which is common for simplicity but isn't a strict rule."] },
        { v: h("What autoencoders are used for") + split(tbl(["Use", "Examples"], [[0, "<b>Denoising</b>: rebuild clean inputs from corrupted ones", "Noisy images, background audio noise, corrupted text"], [1, "<b>Anomaly detection</b>: learn normal, flag <b>high reconstruction error</b>", "Product defects from sensors, fraud in transactions"], [3, "<b>Domain adaptation</b>: change style or domain", "Day → night, colourising black-and-white photos"], [4, "<b>Feature extraction</b>: use the encoder's z", "Classification, 2D/3D visualisation, clustering"]], "sm"), fx(2, "Trained on normal transactions: typical error ≈ 0.02<br>Threshold 0.10. New transaction: error <b>0.35</b> → <b>flag</b>", "sm") + anom + card(5, "bad", "<b>Limitation</b>: bad at generating <b>new</b> samples from a random z. The latent space has <b>gaps</b>. This is the motivation for <b>VAEs</b>."), "even"),
          n: ["Because autoencoders learn efficient encodings, they're useful in lots of places. Data denoising: train the network to rebuild clean inputs from corrupted versions. That cleans noisy images, removes background noise from audio, and corrects corrupted or incomplete text.",
            "Anomaly detection: train only on normal data, so the autoencoder learns what normal looks like. Then anything it reconstructs badly is unusual. This spots defects in manufacturing sensor data and fraud in financial transactions.",
            "Here's the logic with numbers. Trained on normal transactions, the typical reconstruction error is about 0.02. Set a threshold of 0.10. A new transaction comes in with error 0.35. The model has never seen anything like it, so flag it. Quiz point: high reconstruction error suggests an anomaly.",
            "Domain adaptation: transform the style or representation of the input to match a target domain, like turning day scenes into night, or colourising black-and-white images.",
            "Feature extraction: use the encoder's latent vector as features for other tasks, like classification, visualising high-dimensional data in 2D or 3D, or clustering.",
            "The big limitation. A standard autoencoder is not good at generating new samples from a random latent code. Its latent space has gaps, so a random point often decodes to nonsense. Fixing that is exactly what the variational autoencoder does."] }
      ] },
      { t: "Variational autoencoders", sec: [2], scenes: [
        { v: h("VAE: encode to a distribution") + split(svg("vae", 0), list([[0, "Probabilistic twist on the AE. The encoder outputs a <b>distribution</b>: a mean <b>μ</b> and standard deviation <b>σ</b> for each latent dimension."], [1, "<b>Sample</b> z from that distribution, then decode."], [2, "Encoder = <b>q<sub>φ</sub>(z | x)</b>, parameters φ. Decoder = <b>p<sub>θ</sub>(x | z)</b>, parameters θ."], [3, "MNIST: each digit forms its own <b>cluster</b>. Sampling near a cluster gives <b>new digits</b> of that type."]], "tight")),
          n: ["Variational autoencoders come from the probabilistic approach to generative modelling. The encoder doesn't output one point. It outputs the parameters of a probability distribution, usually a Gaussian: a mean, mu, and a standard deviation, sigma, for each latent dimension. Quiz point: a VAE encoder outputs a mean and a standard deviation.",
            "Then we sample a z from that distribution, and the decoder turns it into an output.",
            "In the notation, the encoder is q phi of z given x, a function with parameters phi. The decoder, also called the generative model, is p theta of x given z, with parameters theta.",
            "The slide's MNIST picture shows why this helps. Each handwritten digit forms its own cluster in the latent space. Sample near the cluster for 7 and you get a new 7 that's never existed, but still looks like a 7. The output is diverse and realistic while respecting the structure of the data."] },
        { v: h("The reparameterisation trick") + fx(0, "z = μ + σ · ε, &nbsp;&nbsp; ε ~ N(0, 1)", "c ok") + split(list([[1, "Sampling is <b>random</b>, and you can't backpropagate through a random draw."], [2, "So move the randomness into <b>ε</b>, drawn from a standard normal. Then <b>shift</b> by μ and <b>scale</b> by σ."], [3, "z is now a <b>simple function</b> of μ and σ → gradients flow → train with <b>backprop</b>."], [5, "Lecture writes the draw as θ. ε is standard."]], "tight"), fx(4, "μ = 1.0, σ = 0.5, draw ε = 0.4<br>z = 1.0 + 0.5 × 0.4 = <b>1.2</b><br>another draw ε = −1.2 → z = 1.0 − 0.6 = <b>0.4</b>", "sm"), "even") + at(2, repar),
          n: ["To get a z out of the encoder's distribution, VAEs use the reparameterisation trick: z equals mu plus sigma times epsilon, where epsilon is drawn from a standard normal distribution. This is a fill-in-the-blank favourite: z equals mu plus sigma times epsilon.",
            "Why the trick? Training needs backpropagation, and you can't backpropagate through a random sampling step.",
            "So we move all the randomness into epsilon, which comes from a fixed standard normal. Then we shift it by the learned mean and scale it by the learned standard deviation.",
            "Now z is a simple function of mu and sigma, plus some outside noise. Gradients can flow back through mu and sigma into the encoder, so the whole network trains with ordinary backpropagation.",
            "With numbers: mu is 1.0, sigma is 0.5, and we draw epsilon equal to 0.4. z is 1.0 plus 0.5 times 0.4, which is 1.2. Another draw, epsilon minus 1.2, gives 1.0 minus 0.6, which is 0.4. Same input, different z each time, spread around the mean.",
            "A notation note. The lecture page writes the random draw with theta. Epsilon is the standard symbol, and it avoids confusion with theta, which names the decoder's parameters."] },
        { v: h("VAE loss: reconstruction + KL") + fx(0, "Loss = <b>reconstruction loss</b> + <b>KL</b>( q<sub>φ</sub>(z | x) ‖ N(0, I) )", "c") + split(list([[1, "<b>Reconstruction</b>: output close to input."], [2, "<b>KL</b>: pull each distribution toward the <b>prior N(0, I)</b>."], [4, "<b>Continuity</b> and <b>completeness</b>: any z decodes well."], [5, "<b>Generate</b>: sample z ~ N(0, I) → decode."], [6, "<b>β-VAE</b> (β &gt; 1): <b>disentangled</b> factors."]], "tight"), fx(3, "KL (1 dim) = −½ (1 + log σ² − μ² − σ²)<br>μ = 0, σ = 1: −½ (1 + 0 − 0 − 1) = <b>0</b><br>μ = 1, σ = 1: −½ (1 + 0 − 1 − 1) = <b>0.5</b><br>Drifting from N(0, 1) costs loss.", "sm"), "even"),
          n: ["The VAE loss has two parts: the reconstruction loss, plus a KL divergence term between the encoder's distribution and a standard normal prior. Quiz point: the VAE loss includes reconstruction loss and a KL regularisation term.",
            "The reconstruction loss keeps the output close to the input, exactly as in a plain autoencoder.",
            "The Kullback-Leibler divergence measures how different two distributions are. Here it pulls each encoded distribution toward the prior, a standard normal with mean 0 and variance 1.",
            "For one dimension the KL term is minus a half, times 1 plus log sigma squared, minus mu squared, minus sigma squared. If mu is 0 and sigma is 1, it's exactly 0: no penalty. Move mu to 1 and the penalty is 0.5. So drifting away from the standard normal costs loss, and all the clouds get pulled toward the same region and overlap.",
            "That regularisation gives two properties. Continuity: nearby z values give similar outputs. Completeness: any z you sample gives a meaningful output. That's the filled map from the analogy.",
            "To generate, throw the encoder away, sample z from the standard normal, and decode it into a brand new sample.",
            "And a variant from the revision notes, the beta VAE. With beta greater than 1, the KL term is weighted more heavily. That tends to give disentangled latent factors, where each dimension controls roughly one thing, like smile or pose."] },
        { v: h("Properties of a VAE latent space") + cols(card(0, "", "<b>Dimensionality reduction</b><br>Lower-dimensional than the input: efficient to store and manipulate."), card(1, "", "<b>Smooth and interpolable</b><br>Travel between points → intermediate variations.")) + cols(card(2, "tip", "<b>Generative</b><br>Sample from a standard normal → new data like the training set."), card(3, "tip", "<b>Regularised</b><br>KL keeps the space well structured and easy to sample.")) + card(4, "ana", "AE = pins with gaps. VAE = overlapping <b>clouds</b> filling the map. Any random spot decodes to something sensible."),
          n: ["The four properties of VAE latent representations. Dimensionality reduction: the latent space is lower-dimensional than the input, so it's more efficient to store and manipulate.",
            "Smoothness and interpolability: similar inputs sit at nearby points, so travelling from one point to another produces intermediate variations.",
            "Generative capability: once trained, sampling from the latent space, for example from a standard normal, produces new data resembling the training set.",
            "Regularisation: the KL term pushes the latent distribution toward a standard normal, keeping the space well structured and easy to sample from.",
            "Back to the map. An autoencoder places pins with gaps between them. A VAE places overlapping clouds that fill the map. That's the whole reason VAEs can generate and plain autoencoders can't."] }
      ] },
      { t: "Generative adversarial networks", sec: [3], scenes: [
        { v: h("GAN: a forger and a detective") + split(svg("gan", 0), list([[0, "<b>Goodfellow</b>, <b>2014</b>. Two nets trained together."], [1, "<b>G</b>: noise z → <b>fake G(z)</b>. Tries to <b>fool</b> D."], [2, "<b>D</b>: sample → <b>P(real)</b>. Spots fakes."], [3, "A <b>game</b>: each improves the other."]], "tight")) + stg(1, forger, "16/2.2", "ex6"),
          n: ["Generative adversarial networks were introduced by Ian Goodfellow and colleagues in 2014. They made it possible to create highly realistic images, text and audio. A GAN is two neural networks trained at the same time.",
            "The generator, G, takes random noise z and turns it into a fake sample, G of z. Its goal is to fool the discriminator.",
            "The discriminator, D, takes a sample and outputs the probability that it's real. Its goal is to tell real data from the generator's fakes. Quiz point: the discriminator classifies samples as real or fake. It doesn't create anything.",
            "They're locked in a game-theoretic contest, and each one's improvement forces the other to improve.",
            "The classic analogy: a forger and a detective. As the detective gets better at spotting fakes, the forger has to get better at making them, until the fakes look real. If the quiz asks which model is the forger versus detective game, it's the GAN."] },
        { v: h("How one round of training works") + flow([[0, "G makes fakes from <b>noise</b>"], [1, "D sees fakes <b>and</b> real samples"], [2, "D outputs P(real) for each"], [3, "Update <b>both</b> with their own losses"]], "sm") + split(fx(4, "L<sub>D</sub> = −[ log D(x) + log(1 − D(G(z))) ]", "sm") + fx(5, "L<sub>G</sub> = −log D(G(z))", "sm") + fx(6, "D(x) = 0.9, D(G(z)) = 0.2<br>L<sub>D</sub> = −(ln 0.9 + ln 0.8) = 0.105 + 0.223 = <b>0.328</b><br>L<sub>G</sub> = −ln 0.2 = <b>1.609</b> (G is losing)", "sm"), list([[4, "D wants <b>high D(x)</b> on real data and <b>low D(G(z))</b> on fakes."], [5, "G wants D to say <b>real</b> about its fakes: loss falls as D(G(z)) rises."], [7, "x ~ p<sub>data</sub>: real data. z ~ p<sub>z</sub>: noise. Alternate: train D, then G. G learns <b>only through D's feedback</b>."]], "tight"), "even"),
          n: ["One round of training. The generator creates fake samples from random noise.",
            "The discriminator evaluates those fakes together with real samples from the training data.",
            "It outputs a probability that each sample is real.",
            "Based on those predictions, both networks are updated with their own loss functions. Repeat for many iterations.",
            "The discriminator's loss is minus the log of D of x, minus the log of 1 minus D of G of z. The first term rewards a high score on real data. The second rewards a low score on fakes.",
            "The generator's loss, in the common form, is minus log of D of G of z. It gets smaller as the discriminator gives the fakes a higher probability of being real.",
            "Numbers. Say D gives a real image 0.9, and a fake 0.2. The discriminator loss is minus the natural log of 0.9, plus minus the natural log of 0.8, which is 0.105 plus 0.223, about 0.328. Pretty good for D. The generator's loss is minus log 0.2, about 1.609. High, so G is losing and gets a strong push to improve.",
            "In the formulas, x comes from the real data distribution and z from the noise distribution. Training alternates: update D, then update G. Notice the generator never sees real data directly. It learns only through the discriminator's feedback."] },
        { v: h("The min-max game, success and failure") + fx(0, "min<sub>G</sub> max<sub>D</sub> &nbsp; E<sub>x</sub>[ log D(x) ] + E<sub>z</sub>[ log(1 − D(G(z))) ]", "c") + cols(card(1, "ok", "<b>Success</b><br>Fakes match the real distribution: <b>D ≈ 0.5</b>."), card(2, "bad", "<b>Mode collapse</b><br>G finds <b>one kind</b> of output that fools D and repeats it. <b>Little variety</b>."), card(3, "tip", "<b>After training</b><br>Throw D away. Keep <b>G</b> to create new data from noise.")) + stg(1, collapse, "16/1.35", "ex6") + fx(4, "At D = 0.5: &nbsp; L<sub>G</sub> = −ln 0.5 ≈ 0.693, &nbsp; L<sub>D</sub> = −(ln 0.5 + ln 0.5) ≈ 1.386", "sm"),
          n: ["The whole thing is one min-max objective. D tries to maximise the expected log of D of x plus the expected log of 1 minus D of G of z. G tries to minimise the same quantity. Adversarial training.",
            "When does it succeed? When the generated distribution matches the real one, so the discriminator can't tell them apart and outputs about 0.5 for everything. A coin flip.",
            "The famous failure is mode collapse. The generator finds one kind of output that fools the discriminator and keeps producing it. Imagine a digit GAN that only ever draws perfect 1s. It fools D but misses all the diversity. Quiz point: mode collapse means the generator produces little variety.",
            "And after training, you keep the generator and use it to create new data from noise. The discriminator was just the coach.",
            "For reference, at the balance point where D says 0.5, the generator's loss is minus log 0.5, about 0.693, and the discriminator's is about 1.386."] }
      ] },
      { t: "What GANs can do", sec: [], scenes: [
        { v: h("Applications of GANs") + cols(card(0, "", "<b>Image-to-image translation</b><br>Labels → street, B&amp;W → colour, aerial → map, day → night, edges → photo.<br><b>Style transfer</b>, summer → winter, photo enhancement."), card(1, "tip", "<b>Text-to-image synthesis</b><br>Generate images from descriptions (e.g. birds from a sentence).<br>Content creation, <b>VR</b> scenes, tailored marketing visuals."), card(2, "ex", "<b>3D object generation</b><br>2D sample → 3D mesh → normals and texture → rotate or relight.<br><b>Game</b> assets, <b>architectural</b> models.")) + list([[3, "Why it works: GANs learn <b>complex data distributions</b> → realistic synthetic data. Also <b>data augmentation</b> and <b>super-resolution</b>."]], "tight"),
          n: ["Because GANs learn complex data distributions, they produce very realistic synthetic data. The course lists three application areas. First, image-to-image translation: learning a mapping between visual domains. Labels to street scene, labels to building facade, black-and-white to colour, aerial photo to map, day to night, and edges to photo. That covers style transfer, domain adaptation like turning a summer scene into winter, and photo enhancement from low to high quality.",
            "Second, text-to-image synthesis: generating images from written descriptions, like the slide's birds generated from a sentence about their colours. It helps artists visualise concepts, builds virtual reality environments from narratives, and creates marketing visuals tailored to individual customers.",
            "Third, 3D object generation. A 2D GAN sample is lifted to a 3D mesh, given surface normals and texture, then rotated or relit. That's useful for game assets and architectural visualisation from blueprints.",
            "GANs are also used for data augmentation, adding realistic training examples, and super-resolution, sharpening low resolution images."] }
      ] },
      { t: "Transformers and diffusion", sec: [4], scenes: [
        { v: h("Two more generator families") + split(card(0, "", "<b>Transformer autoregressive</b> (e.g. GPT, optional)<br>Generate <b>one element at a time</b>, each conditioned on everything before.") + fx(1, "p(x) = p(x<sub>1</sub>) · p(x<sub>2</sub> | x<sub>1</sub>) · p(x<sub>3</sub> | x<sub>1</sub>, x<sub>2</sub>) ⋯", "sm") + list([[1, "<b>Attention</b>, pre-trained on huge data, then <b>fine-tuned</b>. Next-token LLMs, chatbots, code."]], "tight"), card(2, "tip", "<b>Diffusion</b><br>Forward: add noise step by step. The model learns to <b>predict the noise</b>. Generate: start from <b>pure noise</b> and <b>denoise</b> repeatedly. Can be <b>guided by a text prompt</b>.") + diffusion(2) + list([[4, "High-quality images. Text-to-image (Stable Diffusion), audio synthesis."]], "tight"), "even"),
          n: ["Two more families, at overview level. Transformer-based autoregressive models, like GPT, are optional in the module. Autoregressive means generating one element at a time, each conditioned on everything generated so far.",
            "Mathematically, the probability of a whole sequence is the probability of the first element, times the second given the first, times the third given the first two, and so on. That's the chain rule again, the same idea as the n-gram from week 8, but with attention looking at the whole history instead of a short window. They're pre-trained on large datasets, then fine-tuned for tasks like chatbots and code generation.",
            "Diffusion models work differently. In the forward process, you take real images and add noise step by step until they're pure static. The model learns to predict the noise that was added at each step. To generate, start from pure random noise and repeatedly remove the predicted noise.",
            "Watch: noise, then a little structure, then a clear image emerges. The process can be guided by a text prompt, which is how text-to-image tools work.",
            "Diffusion models are known for high-quality output, especially images, and they're used for text-to-image generation and audio synthesis."] }
      ] },
      { t: "Comparing AE, VAE and GAN", sec: [], scenes: [
        { v: h("Autoencoder vs VAE vs GAN") + tbl(["", "Autoencoder", "VAE", "GAN"], [[0, "Latent", "One <b>fixed point</b> per input", "A <b>distribution</b> (μ, σ) per input", "<b>Random noise z</b> into G"], [1, "Parts", "Encoder + decoder", "Encoder (outputs μ, σ) + decoder", "<b>Generator + discriminator</b>"], [2, "Training signal", "Reconstruction (MSE or BCE)", "Reconstruction <b>+ KL</b> to N(0, I)", "<b>Adversarial</b>: L<sub>G</sub> and L<sub>D</sub>"], [3, "New data?", "<b>Not reliably</b> (gaps)", "<b>Yes</b>: sample the latent", "<b>Yes</b>: feed noise to G"], [4, "Typical uses", "Denoising, anomaly detection, domain adaptation, features", "Image and music generation, anomaly detection", "Image translation, text-to-image, 3D"], [5, "Watch out", "Can't sample", "Outputs often <b>blurrier</b>", "<b>Mode collapse</b>, unstable training"]], "sm"),
          n: ["Here's the comparison table, worth knowing cold. The latent representation: an autoencoder maps each input to one fixed point. A VAE maps it to a distribution, a mean and variance. A GAN has no encoder at all. It feeds random noise into the generator.",
            "The parts: encoder and decoder for the autoencoder. Encoder that outputs mu and sigma, plus decoder, for the VAE. Generator and discriminator for the GAN.",
            "The training signal: reconstruction loss for the autoencoder. Reconstruction plus KL divergence to a standard normal for the VAE. Adversarial generator and discriminator losses for the GAN.",
            "Can it generate new data? The autoencoder, not reliably, since its latent space isn't built for sampling. The VAE, yes, by sampling the latent distribution. The GAN, yes, by feeding noise to the generator.",
            "Typical uses: autoencoders for denoising, anomaly detection, domain adaptation and feature extraction. VAEs for image and music generation and anomaly detection. GANs for image translation, text-to-image and 3D generation.",
            "And the weaknesses. The autoencoder can't sample. VAE outputs are often a bit blurrier, because averaging over the cloud smooths details. GANs give sharp results but can suffer mode collapse and unstable training."] }
      ] },
      { t: "Ethics and challenges", sec: [], scenes: [
        { v: h("Ethical considerations and challenges") + cols(card(0, "", "<b>Quality control</b><br>Output must be coherent, relevant, up to standard."), card(1, "bad", "<b>Misuse</b><br><b>Deepfakes</b>, misinformation, copyright violations."), card(2, "warn", "<b>Bias and fairness</b><br>Reproduces training-data bias → stereotypes, discrimination.")) + cols(card(3, "warn", "<b>Intellectual property</b><br>Who owns AI-generated content? Unresolved, especially in creative industries."), card(4, "", "<b>Interpretability</b><br>Hard to explain → hard to hold accountable."), card(5, "tip", "<b>Regulation</b><br>Ethical frameworks and guidelines are still being developed.")),
          n: ["Generative AI brings real opportunities, but also issues that must be handled responsibly. Six to know. Quality control: generated content has to be coherent, relevant and meet quality standards.",
            "Misuse: deepfakes, misinformation and copyright violations are the main concerns. A realistic fake video of a politician is the textbook example.",
            "Bias and fairness: models reproduce the biases in their training data, so outputs can reinforce stereotypes or discrimination. If most training photos of doctors are men, generated doctors will be too.",
            "Intellectual property: who owns AI-generated content, and whether training on copyrighted work is allowed, is unresolved, especially in creative industries.",
            "Interpretability: these models are hard to explain, which makes accountability difficult when something goes wrong.",
            "And regulation: ethical frameworks and guidelines are still being developed to address misuse."] }
      ] },
      { t: "Extra notes from the lecture", sec: [], scenes: [
        { v: h("Three extra ideas from your notes") + cols(card(0, "", "<b>Double descent</b><br>As models grow, test error <b>falls</b>, <b>rises</b> near the interpolation threshold, then <b>falls again</b>."), card(2, "", "<b>Thousand Brains</b> (Hawkins)<br>Thousands of <b>cortical columns</b> each model objects from <b>sensory</b> input, then <b>vote</b>."), card(3, "bad", "<b>Catastrophic forgetting</b><br>Cat, dog, then <b>elephant</b>: new training <b>overwrites</b> weights, old tasks are lost.")) + card(1, "warn", "Your note links double descent to <b>saddle points</b>. Careful: saddle points are flat spots that slow training. The usual cause given is the <b>interpolation threshold</b>.") + fx(4, "Fix forgetting: <b>replay</b> old data, or <b>protect</b> weights important to old tasks", "sm"),
          n: ["Your notes end with three extra ideas from the lecture. First, double descent. As you make a model bigger, test error first falls, as classic theory expects. Then it rises, peaking around the size where the model can just fit the training data perfectly, called the interpolation threshold. Then, surprisingly, it falls again as the model keeps growing. It's part of why huge networks generalise better than old theory predicted.",
            "Your note links double descent to saddle points. Treat that link with care. Saddle points are flat spots in the loss surface, a minimum in some directions and a maximum in others. In high dimensions they're very common and they slow training down. They're a real topic, but the standard explanation of double descent is the interpolation threshold. If the lecturer made that connection, use their framing, but don't present it as the textbook cause.",
            "Second, the Thousand Brains theory, from Jeff Hawkins. It proposes that the neocortex is made of thousands of cortical columns, and each one learns a complete model of objects from sensory and movement input. The columns then vote to reach a shared perception. It's an argument for learning from sensory-based data the way brains do.",
            "Third, catastrophic forgetting. Train a network on cats, then on dogs, then on elephants. Each new round of training overwrites the weights and biases, and the network forgets the earlier tasks almost entirely.",
            "The usual fixes are replaying some old data during new training, or regularising so that weights important for old tasks are protected and change less."] }
      ] },
      { t: "Recap and exam checklist", sec: [], scenes: [
        { v: h("Exam checklist") + split(list([[0, "<b>Discriminative</b> P(y | x) vs <b>generative</b> P(x) vs <b>RL</b> policy from rewards."], [1, "Dates: Dartmouth <b>1956</b>, ELIZA 1966, <b>VAE 2013</b>, <b>GAN 2014</b>, GPT-2 2019."], [2, "<b>Latent</b>: AE = fixed point, VAE = distribution."], [3, "<b>AE</b>: reconstruction loss, no labels. High error = <b>anomaly</b>. Can't sample."]], "tight"), list([[4, "<b>VAE</b>: μ and σ, <b>z = μ + σ·ε</b>, loss = reconstruction <b>+ KL</b> to N(0, I). Continuity, completeness. β-VAE."], [5, "<b>GAN</b>: G makes fakes from noise, D says P(real). Min-max. Success: D ≈ 0.5. <b>Mode collapse</b> = little variety. Keep G."], [6, "Autoregressive: p(x<sub>1</sub>)p(x<sub>2</sub> | x<sub>1</sub>)… &nbsp; Diffusion: learn the noise, denoise from pure noise."], [7, "Ethics: quality, <b>deepfakes</b>, bias, IP, interpretability, regulation."]], "tight"), "even"),
          n: ["Let's recap. Discriminative models learn P of y given x, generative models learn P of x and can create samples, and reinforcement learning learns a policy from rewards.",
            "History: Turing 1950, the Dartmouth Conference 1956, ELIZA 1966, AlexNet 2012, VAEs 2013, GANs 2014, GPT-2 2019, DALL-E 2021, Stable Diffusion 2022.",
            "The latent space is a compressed, smooth space you can sample from. An autoencoder maps each input to a fixed point, a VAE to a distribution.",
            "Autoencoder: encoder to z to decoder, trained with reconstruction loss like mean squared error, no labels. A smaller latent space is a tighter bottleneck. High reconstruction error flags an anomaly. And it can't reliably generate new samples.",
            "VAE: the encoder outputs mu and sigma, z equals mu plus sigma times epsilon, and the loss is reconstruction plus KL divergence to a standard normal. That gives continuity and completeness, so sampling works.",
            "GAN: the generator makes fakes from noise, the discriminator outputs the probability a sample is real. It's a min-max game. Success means the discriminator is stuck at about 0.5. Mode collapse means little variety. After training, keep the generator.",
            "Autoregressive models multiply conditional probabilities one element at a time. Diffusion models learn to predict noise and generate by denoising from pure noise.",
            "And the ethics: quality control, deepfakes and misuse, bias, intellectual property, interpretability and regulation. Now try the week 9 quiz. Good luck."] }
      ] }
    ]
  };
})();
